# Get-WinEvent出力を改善するためのスクリプト

# Function 1: Get-GuidName - GUIDを人間が読める名前に変換するヘルパー関数
Function Get-GuidName ($Guid) {
    Begin {
        # ここに監視対象のObjectGUIDとそのフレンドリー名のマッピングを定義します。
        # 'ObjectGUIDの値' = 'フレンドリーなオブジェクト名'
        # 例: '%{0ca1d341-b9ee-4d46-ab3b-3a2732aa4b51}' は Domain Admins のGUIDを模倣したものです。
        # 実際の環境に合わせて値を置き換えてください。
        $ObjectTable = @{
            '%{0ca1d341-b9ee-4d46-ab3b-3a2732aa4b51}' = 'Domain Admins'
            # 他のGUIDと名前のマッピングをここに追加できます
        }
    }
    Process {
        $Value = $ObjectTable[$Guid]
        If (!$Value) {
            $Value = $Guid # マッピングが見つからない場合は元のGUIDを返す
        }
    }
    End {
        return $Value
    }
}

# Function 2: Get-AccessName - アクセスマスク（16進数）を人間が読める名前に変換するヘルパー関数
Function Get-AccessName ($AccessMask) {
    Begin {
        # ここにアクセスマスク（16進数）とそのフレンドリー名のマッピングを定義します。
        # '16進数のアクセスマスク' = 'フレンドリーなアクセス名'
        $AccessTable = @{
            '0x10'    = 'Read Property'
            '0x20000' = 'READ_CONTROL'
            # 他のアクセスマスクと名前のマッピングをここに追加できます
            # 例:
            # '0x1'     = 'List Contents'
            # '0x2'     = 'Write Property'
            # '0x4'     = 'Create Child'
            # '0x8'     = 'Delete Child'
            # '0x100'   = 'Generic Read'
            # '0x200'   = 'Generic Write'
            # '0x400'   = 'Generic Execute'
        }
    }
    Process {
        $Value = $AccessTable[$AccessMask]
        If (!$Value) {
            $Value = $AccessMask # マッピングが見つからない場合は元のアクセスマスクを返す
        }
    }
    End {
        return $Value
    }
}

# XPathフィルターを定義します
# SubjectUserSidとObjectNameの値は、実際の環境に合わせて置き換える必要があります。
# 'S-1-5-21-...' は offsec アカウントのSIDの例です。
# '%{0ca1d341-b9ee-4d46-ab3b-3a2732aa4b51}' は Domain Admins グループのObjectGUIDの例です。
$FilterXML = @'
<QueryList>
  <Query Id="0" Path="Security">
    <Select Path="Security">
     *[System[(EventID=4662)]] and *[EventData[(Data[@Name='SubjectUserSid']='S-1-5-21-2154860315-1826001137-329834519-1107')]] and *[EventData[(Data[@Name='ObjectName']='%{0ca1d341-b9ee-4d46-ab3b-3a2732aa4b51}')]] and *[EventData[(Data[@Name='OperationType']='Object Access')]]
   </Select>
  </Query>
</QueryList>
'@

Write-Host "イベントログからデータを取得中..."

# Get-WinEventでフィルターを適用し、結果を取得
$Logs = Get-WinEvent -FilterXml $FilterXML -ErrorAction SilentlyContinue

# ログが取得されたか確認
if ($Logs -eq $null) {
    Write-Warning "指定されたフィルター条件に一致するイベントは見つかりませんでした。"
    exit
}

$OutputResults = @()

# 各イベントを処理し、必要な情報を抽出・変換して表示
ForEach ($L in $Logs) {
   [xml]$XML = $L.toXml() # イベントをXML形式に変換

   # XMLからデータポイントを抽出
   $TimeStamp       = $XML.Event.System.TimeCreated.SystemTime
   # EventDataのインデックスはイベントによって異なる場合があるので注意。
   # Data[1]は通常SubjectUserName、Data[6]はObjectName、Data[10]はAccessMaskであることが多い。
   $SubjectUserName = $XML.Event.EventData.Data | Where-Object {$_.Name -eq 'SubjectUserName'} | Select-Object -ExpandProperty '#text'
   $ObjectNameRaw   = $XML.Event.EventData.Data | Where-Object {$_.Name -eq 'ObjectName'} | Select-Object -ExpandProperty '#text'
   $AccessMaskRaw   = $XML.Event.EventData.Data | Where-Object {$_.Name -eq 'AccessMask'} | Select-Object -ExpandProperty '#text'

   # ヘルパー関数を使用して名前を変換
   $ObjectName  = Get-GuidName -Guid $ObjectNameRaw
   $AccessName  = Get-AccessName -AccessMask $AccessMaskRaw

   # カスタムオブジェクトを作成して結果に追加
   $OutputResults += [PSCustomObject]@{
       'TimeStamp'       = $TimeStamp
       'SubjectUserName' = $SubjectUserName
       'ObjectName'      = $ObjectName
       'AccessName'      = $AccessName
   }
}

# 結果を表形式で表示
$OutputResults | Format-Table -AutoSize

Write-Host "スクリプトの実行が完了しました。"
