function Get-BadPwdCount {
    [CmdletBinding()]
    Param (
        # 特定のユーザー名ではなく、ミスのあった人を一覧表示するスイッチ
        [Parameter(Mandatory = $false, ParameterSetName = 'List')]
        [switch]$List,

        # 特定のユーザーをピンポイントで調べたい場合に使用
        [Parameter(Mandatory = $false, ParameterSetName = 'List')]
        [string]$Username,

        # 統計モード：期待される失敗率（％）を入力（例: "10"）
        [Parameter(Mandatory = $false, ParameterSetName = 'Statistics')]
        [string]$Expected
    )

    # 【準備フェーズ】ドメイン情報の取得と検索設定
    Begin { 
        # パスワードミス回数(badPwdCount)はPDC（プライマリドメインコントローラー）が
        # 正確な値を保持しているため、PDCを特定して接続先に設定する
        $Domain = [System.DirectoryServices.ActiveDirectory.Domain]::GetCurrentDomain()
        $PDC = $Domain.PdcRoleOwner
        $SearchRoot = "LDAP://{0}/DC={1}" -f $PDC, $Domain.Name.Replace('.', ',DC=')

        # AD検索用オブジェクトの作成
        $Searcher = New-Object System.DirectoryServices.DirectorySearcher([ADSI]$SearchRoot)

        # 必要な属性（ユーザー名とミス回数）だけをロードしてメモリを節約
        $Searcher.PropertiesToLoad.Add("sAMAccountName") | Out-Null
        $Searcher.PropertiesToLoad.Add("badPwdCount") | Out-Null

        # 1000件以上のユーザーがいる環境でもエラーにならないように設定
        $Searcher.PageSize = 1000

        # 特定のユーザーか、あるいは「有効な全ユーザー」かをフィルターで指定
        If ($Username) {
            $Searcher.Filter = "(sAMAccountName=$Username)"
        } else {
            # 有効なユーザーアカウントのみを対象とする（無効化されたアカウントを除外）
            $Searcher.Filter = "(&(objectCategory=person)(objectClass=user)(!userAccountControl:1.2.840.113556.1.4.803:=2))"
        }

        # ADに対して検索を実行し、結果を $Users に格納
        $Users = $Searcher.FindAll()
    }

    # 【実行フェーズ】取得したデータの加工
    Process {       
        # パターン1：一覧表示モード (-List スイッチがある場合)
        if ($List) {
            # ミス回数が0より大きいユーザーのみを抽出して表形式で出力
            $Results = $Users | Where-Object { $_.Properties.badpwdcount -gt 0 } | ForEach-Object {
                [PSCustomObject]@{
                    'SamAccountName' = $($_.Properties.samaccountname); 
                    'BadPwdCount'    = $($_.Properties.badpwdcount) 
                }
            }
        }

        # パターン2：統計モード (スイッチがない場合。パスワードスプレー検知用)
        if (!$List) {
            # ミスがあるユーザーの総数をカウント
            $BadPwdCount = $($Users | Where-Object { $_.Properties.badpwdcount -gt 0 }).Count

            # ドメイン全体の「失敗率」を計算（四捨五入して小数点第2位まで）
            $Actual = [math]::Round($BadPwdCount / $Users.Count * 100, 2)

            # 統計結果をオブジェクトとして作成
            $Results = [PSCustomObject]@{
                'TotalUsers' = $Users.Count;     # 全ユーザー数
                'Expected'   = "$Expected%";     # 許容できる失敗率(入力値)
                'Actual'     = "$Actual%"        # 実際の失敗率(計算値)
            }
        }
    }

    # 【終了フェーズ】結果を画面に返す
    End { 
        return $Results
    }
}
