Function Get-FailureReason ($StatusCode) {
    Begin {
        # よくある失敗理由の対応表を作成
        $StatusTable = @{
            '0xC000006A' = 'パスワードの間違い（入力ミス）'
            '0XC000006D' = 'ユーザー名が存在しない、または認証情報の誤り'
        }
    }
    Process {
        # テーブルから理由を検索
        $Value = $StatusTable[$StatusCode]
        # 表にないコードの場合は、そのままのコードを返す
        If (!$Value) {
            $Value = $StatusCode
        }
    }
    End {
        return $Value
    }
}

# 【検索フィルタ】セキュリティログから「jim」の「失敗ログ（4625）」だけを抽出
$FilterXML = @'
<QueryList>
  <Query Id="0" Path="Security">
    <Select Path="Security">
    # イベントID 4625（ログオン失敗）を指定
    *[System[(EventID=4625)]]
    and
    # ターゲットユーザー名が「jim」であるものに限定
    *[EventData[Data[@Name='TargetUserName'] and (Data='jim')]]
    </Select>
  </Query>
</QueryList>
'@

# ログを取得
$Logs = Get-WinEvent -FilterXml $FilterXML

# 取得した各ログをループ処理して詳細情報を解析
ForEach ($L in $Logs) {
    # ログの中身（XML形式）を解析可能なオブジェクトに変換
    [xml]$XML = $L.toXml()

    # XMLのデータ構造から必要な項目を抜き出す
    $TimeStamp = $XML.Event.System.TimeCreated.SystemTime               # 発生時刻
    $TargetUserName = $XML.Event.EventData.Data[5].'#text'             # 狙われたユーザー名

    # 失敗理由のコード（インデックス9番）を取得し、関数で文字に変換
    $FailureReason = Get-FailureReason -StatusCode $($XML.Event.EventData.Data[9].'#text')

    $LogonType = $XML.Event.EventData.Data[10].'#text'                 # ログオンの種類（3=ネットワーク等）
    $WorkstationName = $XML.Event.EventData.Data[13].'#text'           # 攻撃元のコンピュータ名

    # 最後に、見やすいカスタムオブジェクトとして出力
    [PSCustomObject]@{
        'TimeStamp'       = $TimeStamp; 
        'TargetUserName'  = $TargetUserName; 
        'FailureReason'   = $FailureReason; 
        'LogonType'       = $LogonType ; 
        'WorkstationName' = $WorkstationName 
    }
}
