Function Get-FailureReason ($StatusCode) {
    Begin {
        # エラーコードと理由の対応表
        $StatusTable = @{
            '0xC000006A' = 'パスワードの間違い（入力ミス）'
            '0XC000006D' = 'ユーザー名が存在しない、または認証情報の誤り'
        }
    }
    Process {
        # コードを照合
        $Value = $StatusTable[$StatusCode]
        # 表にないコード（例: 0xc0000234 ロックアウト中など）はコードをそのまま返す
        If (!$Value) {
            $Value = $StatusCode
        }
    }
    End {
        return $Value
    }
}

# 【検索フィルタ】セキュリティログから「すべての失敗ログ（4625）」を取得
$FilterXML = @'
    <QueryList>
      <Query Id="0" Path="Security">
        # ユーザー名で絞り込まず、イベントID 4625 のみを条件にする
        <Select Path="Security">*[System[(EventID=4625)]]</Select>
      </Query>
    </QueryList>
'@

# ログを検索して一括取得
$Logs = Get-WinEvent -FilterXml $FilterXML

# 取得したすべての失敗ログを順番に解析
ForEach ($L in $Logs) {
    # ログ（XML形式）をオブジェクトとして解析できるように変換
    [xml]$XML = $L.toXml()

    # XMLのデータ構造（EventData > Data）から必要な項目を抜き出す
    # 注意: インデックス番号（[1]など）はログのデータ構造に依存します
    $TimeStamp = $XML.Event.System.TimeCreated.SystemTime               # 発生時刻
    $SubjectUserName = $XML.Event.EventData.Data[1].'#text'            # ログオンを試みた側のアカウント（システムなど）
    $TargetUserName = $XML.Event.EventData.Data[5].'#text'             # ログインに失敗したターゲットのアカウント

    # 失敗理由のコード（インデックス9番）を抽出し、関数でテキスト化
    $FailureReason = Get-FailureReason -StatusCode $($XML.Event.EventData.Data[9].'#text')

    $LogonType = $XML.Event.EventData.Data[10].'#text'                 # ログオンの種類（例: 3はネットワーク経由）
    $WorkstationName = $XML.Event.EventData.Data[13].'#text'           # 攻撃元（失敗が発生した端末）の名称

    # 抽出したデータを整理して出力
    [PSCustomObject]@{
        'TimeStamp'       = $TimeStamp; 
        'TargetUserName'  = $TargetUserName;     # 狙われたのは誰か
        'FailureReason'   = $FailureReason;      # なぜ失敗したか
        'LogonType'       = $LogonType ;         # どんな方法で来たか
        'WorkstationName' = $WorkstationName     # どこから来たか（重要！）
    }
}

